window.docContents[186].resolve({"/Automation/#Logical-Foundations--Automation___-More-Automation":{"contents":"\n\nConsider the proof below. Notice all the repetition and near-repetition...\n\ntheorem Perm3_In_old (α : Type) (x : α) (l₁ l₂ : List α) :\n    Perm3 l₁ l₂ → x ∈ l₁ → x ∈ l₂ := by\n  intro hPerm hIn\n  induction hPerm with\n  | perm3_swap12 =>\n    rw [List.mem_cons, List.mem_cons, List.mem_cons] at *\n    obtain h | h | h | h := hIn\n    . right; left; assumption\n    . left; assumption\n    . right; right; left; assumption\n    . contradiction\n  | perm3_swap23 =>\n    rw [List.mem_cons, List.mem_cons, List.mem_cons] at *\n    obtain h | h | h | h := hIn\n    . left; assumption\n    . right; right; left; assumption\n    . right; left; assumption\n    . contradiction\n  | perm3_trans _ _ _ _ _ ih₁2 ih₂3 =>\n    apply ih₂3; apply ih₁2; apply hIn\ntheorem Perm3_In_old (α : Type) (x : α) (l₁ l₂ : List α) :\n    Perm3 l₁ l₂ → x ∈ l₁ → x ∈ l₂ := by\n  intro hPerm hIn\n  induction hPerm with\n  | perm3_swap12 =>\n    rw [List.mem_cons, List.mem_cons, List.mem_cons] at *\n    obtain h | h | h | h := hIn\n    . right; left; assumption\n    . left; assumption\n    . right; right; left; assumption\n    . contradiction\n  | perm3_swap23 =>\n    rw [List.mem_cons, List.mem_cons, List.mem_cons] at *\n    obtain h | h | h | h := hIn\n    . left; assumption\n    . right; right; left; assumption\n    . right; left; assumption\n    . contradiction\n  | perm3_trans _ _ _ _ _ ih₁2 ih₂3 =>\n    apply ih₂3; apply ih₁2; apply hIn\ntheorem Perm3_In_old (α : Type) (x : α) (l₁ l₂ : List α) :\n    Perm3 l₁ l₂ → x ∈ l₁ → x ∈ l₂ := by\n  intro hPerm hIn\n  induction hPerm with\n  | perm3_swap12 =>\n    rw [List.mem_cons, List.mem_cons, List.mem_cons] at *\n    obtain h | h | h | h := hIn\n    . right; left; assumption\n    . left; assumption\n    . right; right; left; assumption\n    . contradiction\n  | perm3_swap23 =>\n    rw [List.mem_cons, List.mem_cons, List.mem_cons] at *\n    obtain h | h | h | h := hIn\n    . left; assumption\n    . right; right; left; assumption\n    . right; left; assumption\n    . contradiction\n  | perm3_trans _ _ _ _ _ ih₁2 ih₂3 =>\n    apply ih₂3; apply ih₁2; apply hIn\n\n\nIn this file, we will introduce tactics that will shrink this proof from\naround eighteen lines to two.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations","header":"10. Automation: More Automation","id":"/Automation/#Logical-Foundations--Automation___-More-Automation"}});